package com.autocare.platform.order;

import com.autocare.platform.common.write.WriteIntegrityService;
import com.autocare.platform.service.MerchantActor;
import com.autocare.platform.vehicle.VehicleOwner;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.nio.file.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.core.io.FileSystemResource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.springframework.jdbc.datasource.init.ScriptUtils;
import org.springframework.web.server.ResponseStatusException;
import org.testcontainers.containers.MySQLContainer;
import org.testcontainers.junit.jupiter.*;
import static org.junit.jupiter.api.Assertions.*;

@Testcontainers class JdbcInvitationsTest {
 @Container static MySQLContainer<?> mysql=new MySQLContainer<>("mysql:8.0").withCommand("--log-bin-trust-function-creators=1");
 static JdbcTemplate jdbc;ObjectMapper json=new ObjectMapper();ReservationStore db;InvitationRegistration registration;Invitations invitations;Time clock;VehicleOwner owner,other;MerchantActor staff,peer;
 static class Time extends Clock{Instant value=Instant.now().truncatedTo(java.time.temporal.ChronoUnit.SECONDS);public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId z){return Clock.fixed(value,z);}public Instant instant(){return value;}}
 @BeforeAll static void schema()throws Exception{var ds=new DriverManagerDataSource(mysql.getJdbcUrl(),mysql.getUsername(),mysql.getPassword());jdbc=new JdbcTemplate(ds);try(var c=ds.getConnection();var paths=Files.list(Path.of("..","docs","sql","migrations"))){for(var p:paths.filter(p->p.toString().endsWith(".sql")).sorted().toList())ScriptUtils.executeSqlScript(c,new FileSystemResource(p));}}
 @BeforeEach void setup(){jdbc.execute("DROP TRIGGER IF EXISTS fail_invite_audit");for(String t:List.of("invite_phone_evidence","invite_registration","invite_code","auth_session","idempotency_record","audit_log","user","staff_account","merchant"))jdbc.update("DELETE FROM `"+t+"`");clock=new Time();var manager=new DataSourceTransactionManager(jdbc.getDataSource());db=new ReservationStore(jdbc,json,new WriteIntegrityService(jdbc,json,manager),clock,manager);registration=new InvitationRegistration(db);invitations=new Invitations(db,false);jdbc.update("INSERT INTO user(id,openid) VALUES(1,'old-owner'),(2,'old-peer')");jdbc.update("INSERT INTO merchant(id,merchant_type,name,address,status) VALUES(1,2,'synthetic-A','test-address',1),(2,2,'synthetic-B','test-address',1)");jdbc.update("INSERT INTO staff_account(id,merchant_id,role,account,status) VALUES(1,1,'STAFF','synthetic-A','ACTIVE'),(2,2,'STAFF','synthetic-B','ACTIVE')");owner=new VehicleOwner(1,session(1,"user","OWNER","test-app",null),Instant.now().plusSeconds(3600));other=new VehicleOwner(2,session(2,"user","OWNER","test-app",null),Instant.now().plusSeconds(3600));staff=new MerchantActor(1,1,"STAFF",session(1,"staff_account","STAFF","merchant-account",1L),Instant.now().plusSeconds(3600));peer=new MerchantActor(2,2,"STAFF",session(2,"staff_account","STAFF","merchant-account",2L),Instant.now().plusSeconds(3600));}
 String key(){return UUID.randomUUID().toString();}String session(long id,String type,String role,String app,Long shop){String s=key();jdbc.update("INSERT INTO auth_session(id,subject_type,subject_id,role,app_id,merchant_id,refresh_hash,expires_at) VALUES(?,?,?,?,?,?,?,DATE_ADD(UTC_TIMESTAMP(),INTERVAL 1 HOUR))",s,type,id,role,app,shop,key());return s;}
 String code(){return invitations.create(owner,key(),json.createObjectNode()).path("data").path("code").path("value").textValue();}
 String otherCode(){return invitations.create(other,key(),json.createObjectNode()).path("data").path("code").path("value").textValue();}
 long register(String openid,String code,String source){return registration.register(openid,code,source,"test-app");}
 String state(long id){return jdbc.queryForObject("SELECT qualification_status FROM invite_registration WHERE user_id=?",String.class,id);}
 long qualified(){return ((Number)invitations.progress(owner).get("qualified_count")).longValue();}
 int count(String table){return jdbc.queryForObject("SELECT COUNT(*) FROM "+table,Integer.class);}
 @Test void codeReadIsSideEffectFreeAndCreateIsStableAcrossKeysAndExpiry(){assertNull(invitations.code(owner).get("code"));assertEquals(0,count("invite_code"));String k=key();var r=invitations.create(owner,k,json.createObjectNode());assertEquals(r,invitations.create(owner,k,json.createObjectNode()));String c=r.path("data").path("code").path("value").textValue();jdbc.update("UPDATE idempotency_record SET expires_at=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 1 DAY)");assertEquals(c,invitations.create(owner,k,json.createObjectNode()).path("data").path("code").path("value").textValue());assertEquals(c,invitations.create(owner,key(),json.createObjectNode()).path("data").path("code").path("value").textValue());assertEquals(1,count("invite_code"));assertEquals(1,count("audit_log"));assertFalse(jdbc.queryForObject("SELECT after_state FROM audit_log",String.class).contains(c));}
 @Test void newRegistrationAndVerifiedPhoneQualifyOnce(){String c=code();long id=register("new-a",c,"VERIFIED_WECHAT");assertEquals("PENDING",state(id));assertEquals(0,qualified());registration.bindPhone(id,"13800138001","test-app",true);assertEquals("QUALIFIED",state(id));assertEquals(1,qualified());registration.bindPhone(id,"13800138001","test-app",true);assertEquals(1,qualified());assertEquals(1,count("invite_phone_evidence"));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM audit_log WHERE action='INVITE_QUALIFY'",Integer.class));}
 @Test void existingAccountsAndRepeatedLoginNeverAcquireOrChangeAttribution(){String c=code(),different=otherCode();assertEquals(2,register("old-peer",c,"VERIFIED_WECHAT"));assertEquals(0,count("invite_registration"));long id=register("new-a",c,"VERIFIED_WECHAT");assertEquals(id,register("new-a",different,"VERIFIED_WECHAT"));assertEquals(1L,jdbc.queryForObject("SELECT source_id FROM invite_registration WHERE user_id=?",Long.class,id));registration.bindPhone(2,"13800138002","test-app",true);assertEquals(0,qualified());}
 @Test void unknownAndTestEvidenceCannotBecomeFormalAfterPhoneBinding(){String c=code();long u=register("unknown",c,"UNKNOWN"),t=register("test",c,"TEST");registration.bindPhone(u,"13800138003","test-app",true);registration.bindPhone(t,"13800138004","test-app",true);assertEquals("UNKNOWN",state(u));assertEquals("TEST",state(t));assertEquals(0,qualified());var p=invitations.progress(owner);assertEquals(1L,p.get("unknown_total"));assertEquals(1L,p.get("test_total"));}
 @Test void noCodeCannotBeAddedOnNextLogin(){long id=register("new-a",null,"VERIFIED_WECHAT");assertEquals("REJECTED",state(id));register("new-a",code(),"VERIFIED_WECHAT");assertNull(jdbc.queryForObject("SELECT invite_code_id FROM invite_registration WHERE user_id=?",Long.class,id));}
 @Test void invalidCodeDoesNotBlockRegistrationOrAllowLaterAttribution(){long id=register("new-a","a".repeat(32),"VERIFIED_WECHAT");assertEquals("INVALID_CODE",jdbc.queryForObject("SELECT attribution_result FROM invite_registration WHERE user_id=?",String.class,id));register("new-a",code(),"VERIFIED_WECHAT");assertEquals("REJECTED",state(id));}
 @Test void disabledInviterCannotCreateNewAttribution(){String c=code();jdbc.update("UPDATE user SET status=2 WHERE id=1");long id=register("new-a",c,"VERIFIED_WECHAT");assertEquals("SOURCE_UNAVAILABLE",jdbc.queryForObject("SELECT attribution_result FROM invite_registration WHERE user_id=?",String.class,id));assertEquals("REJECTED",state(id));}
 @Test void sourceDisabledBeforeQualificationRejectsWithoutChangingFrozenAttribution(){String c=code();long id=register("new-a",c,"VERIFIED_WECHAT");jdbc.update("UPDATE user SET status=2 WHERE id=1");registration.bindPhone(id,"13800138005","test-app",true);assertEquals("REJECTED",state(id));assertEquals("ATTRIBUTED",jdbc.queryForObject("SELECT attribution_result FROM invite_registration WHERE user_id=?",String.class,id));assertEquals("SOURCE_UNAVAILABLE",jdbc.queryForObject("SELECT qualification_reason FROM invite_registration WHERE user_id=?",String.class,id));}
 @Test void oldVerifiedPhoneHistoryCannotBeRecycledAfterPhoneChange(){registration.bindPhone(2,"13800138006","test-app",true);jdbc.update("UPDATE user SET phone=NULL WHERE id=2");long id=register("new-a",code(),"VERIFIED_WECHAT");registration.bindPhone(id,"13800138006","test-app",true);assertEquals("REJECTED",state(id));assertEquals("PHONE_SEEN",jdbc.queryForObject("SELECT qualification_reason FROM invite_registration WHERE user_id=?",String.class,id));assertEquals(0,qualified());}
 @Test void unverifiedPhoneAndDifferentAppNeverQualify(){long a=register("new-a",code(),"VERIFIED_WECHAT");registration.bindPhone(a,"13800138007","test-app",false);assertEquals("PENDING",state(a));assertEquals(0,count("invite_phone_evidence"));registration.bindPhone(a,"13800138007","other-app",true);assertEquals("PENDING",state(a));assertEquals(0,qualified());}
 @Test void clockRegressionCannotCreateQualificationBeforeRegistration(){long id=register("new-a",code(),"VERIFIED_WECHAT");clock.value=clock.value.minusSeconds(1);assertEquals(503,assertThrows(ResponseStatusException.class,()->registration.bindPhone(id,"13800138012","test-app",true)).getStatusCode().value());assertEquals("PENDING",state(id));assertEquals(0,count("invite_phone_evidence"));assertNull(jdbc.queryForObject("SELECT phone FROM user WHERE id=?",String.class,id));}
 @Test void logoutDuringPhoneExchangeBlocksPhoneAndQualificationCommit(){long id=register("new-a",code(),"VERIFIED_WECHAT");var a=new VehicleOwner(id,session(id,"user","OWNER","test-app",null),Instant.now().plusSeconds(3600));jdbc.update("UPDATE auth_session SET revoked_at=UTC_TIMESTAMP() WHERE id=?",a.session());assertEquals(401,assertThrows(ResponseStatusException.class,()->registration.bindPhone(a,"13800138013","test-app",true)).getStatusCode().value());assertEquals("PENDING",state(id));assertEquals(0,count("invite_phone_evidence"));assertNull(jdbc.queryForObject("SELECT phone FROM user WHERE id=?",String.class,id));}
 @Test void beijingMonthUsesQualificationNotRegistrationAndHistoryPersists(){clock.value=Instant.parse("2026-10-31T15:59:59Z");long id=register("new-a",code(),"VERIFIED_WECHAT");clock.value=Instant.parse("2026-10-31T16:00:00Z");registration.bindPhone(id,"13800138008","test-app",true);assertEquals("2026-11",invitations.progress(owner).get("month"));assertEquals(1,qualified());clock.value=Instant.parse("2026-11-30T16:00:00Z");assertEquals(0,qualified());assertEquals(1L,invitations.records(owner,1).get("total"));}
 @Test void qualificationMonthAndTimestampStayConsistentWhenClockCrossesMonthBoundary(){
  clock.value=Instant.parse("2026-10-31T15:59:56Z");
  long id=register("month-boundary",code(),"VERIFIED_WECHAT");
  var movingClock=new Time(){
   int reads;
   @Override public Instant instant(){return Instant.parse("2026-10-31T15:59:57Z").plusSeconds(reads++);}
  };
  var manager=new DataSourceTransactionManager(jdbc.getDataSource());
  var movingDb=new ReservationStore(jdbc,json,new WriteIntegrityService(jdbc,json,manager),movingClock,manager);
  new InvitationRegistration(movingDb).bindPhone(id,"13800138014","test-app",true);
  var stored=jdbc.queryForMap("SELECT qualified_at,reward_month FROM invite_registration WHERE user_id=?",id);
  clock.value=ReservationStore.instant(stored.get("qualified_at"));
  String actualMonth=clock.value.atZone(ZoneId.of("Asia/Shanghai")).toLocalDate().toString().substring(0,7);
  assertEquals(actualMonth,stored.get("reward_month"));
  assertEquals(1,qualified());
  assertEquals(1L,new InviteDiagnosisPolicies(db,null).current(owner).get("qualified_count"));
 }
 @Test void cyclesHaveIncrementalTargetsAndRepeatAfterTen(){for(long n=0;n<=25;n++){var c=Invitations.cycle(n);assertEquals(n/10,c.get("completed_cycles"));assertTrue(((Number)c.get("next_threshold")).longValue()>n);assertTrue(((Number)c.get("tier_count")).longValue()<((Number)c.get("tier_target")).longValue());}assertEquals(3,Invitations.cycle(3).get("tier"));assertEquals(10L,Invitations.cycle(6).get("next_threshold"));assertEquals(1,Invitations.cycle(10).get("tier"));assertEquals(11L,Invitations.cycle(10).get("next_threshold"));}
 @Test void staffAttributionIsScopedToCurrentEmployeeAndShop(){String c=invitations.create(staff,key(),json.createObjectNode()).path("data").path("code").path("value").textValue();long id=register("new-a",c,"VERIFIED_WECHAT");registration.bindPhone(id,"13800138009","test-app",true);assertEquals(1L,invitations.records(staff,1).get("total"));assertEquals(0L,invitations.records(peer,1).get("total"));assertEquals(0L,invitations.records(owner,1).get("total"));var row=((List<?>)invitations.records(staff,1).get("items")).get(0);String view=json.valueToTree(row).toString();assertFalse(view.contains("138001"));assertFalse(view.contains("new-a"));assertFalse(view.contains("user_id"));assertEquals(1L,jdbc.queryForObject("SELECT merchant_id FROM invite_registration WHERE user_id=?",Long.class,id));}
 @Test void staffTransferAndRevocationDisableOldCodes(){String c=invitations.create(staff,key(),json.createObjectNode()).path("data").path("code").path("value").textValue();jdbc.update("UPDATE staff_account SET merchant_id=2 WHERE id=1");long id=register("new-a",c,"VERIFIED_WECHAT");assertEquals("REJECTED",state(id));assertThrows(ResponseStatusException.class,()->invitations.code(staff));}
 @Test void revokedSessionCannotReplayCodeCreation(){String k=key();invitations.create(owner,k,json.createObjectNode());jdbc.update("UPDATE auth_session SET revoked_at=UTC_TIMESTAMP() WHERE id=?",owner.session());assertEquals(401,assertThrows(ResponseStatusException.class,()->invitations.create(owner,k,json.createObjectNode())).getStatusCode().value());}
 @Test void concurrentSameOpenidCreatesOneImmutableSource()throws Exception{String a=code(),b=otherCode();var start=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);try{var f=pool.submit(()->{start.await();return register("new-a",a,"VERIFIED_WECHAT");});var g=pool.submit(()->{start.await();return register("new-a",b,"VERIFIED_WECHAT");});start.countDown();assertEquals(f.get(30,TimeUnit.SECONDS),g.get(30,TimeUnit.SECONDS));assertEquals(1,count("invite_registration"));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM audit_log WHERE action='INVITE_REGISTER'",Integer.class));}finally{pool.shutdownNow();}}
 @Test void concurrentPhoneBindingHasOneQualification()throws Exception{long id=register("new-a",code(),"VERIFIED_WECHAT");var start=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);try{var tasks=new ArrayList<Future<?>>();for(int i=0;i<2;i++)tasks.add(pool.submit(()->{start.await();registration.bindPhone(id,"13800138010","test-app",true);return null;}));start.countDown();for(var f:tasks)f.get(30,TimeUnit.SECONDS);assertEquals(1,qualified());assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM audit_log WHERE action='INVITE_QUALIFY'",Integer.class));}finally{pool.shutdownNow();}}
 @Test void auditFailureRollsBackRegistrationAndPhoneQualification(){String c=code();jdbc.execute("CREATE TRIGGER fail_invite_audit BEFORE INSERT ON audit_log FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='synthetic rollback'");assertThrows(Exception.class,()->register("new-a",c,"VERIFIED_WECHAT"));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM user WHERE openid='new-a'",Integer.class));jdbc.execute("DROP TRIGGER fail_invite_audit");long id=register("new-a",c,"VERIFIED_WECHAT");jdbc.execute("CREATE TRIGGER fail_invite_audit BEFORE INSERT ON audit_log FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='synthetic rollback'");assertThrows(Exception.class,()->registration.bindPhone(id,"13800138011","test-app",true));assertEquals("PENDING",state(id));assertEquals(0,count("invite_phone_evidence"));assertNull(jdbc.queryForObject("SELECT phone FROM user WHERE id=?",String.class,id));}
}
